+/** A condition accepted by conditional option helpers. */
+export type OptionCondition = string | OptionDependencyCondition | OptionDependency;
+
+function normalizeOptionCondition(condition: OptionCondition): OptionDependency {
+  return typeof condition === "string" ? { option: condition } : condition;
+}
+
+function optionNamesFromSpec(flagSpec: OptionName | readonly OptionName[]): readonly OptionName[] {
+  return typeof flagSpec === "string" ? [flagSpec] : flagSpec;
+}
+
+/**
+ * Creates an option that is required when its condition is not satisfied.
+ * @since 0.11.0
+ */
+export function requiredWhen<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  const dependsOn = { ...normalizeOptionCondition(condition), required: true };
+  const names = optionNamesFromSpec(flagSpec);
+  return valueParser == null
+    ? option(...names, { dependsOn })
+    : option(...names, valueParser, { dependsOn });
+}
+
+/**
+ * Creates an option that is visible only when its condition is satisfied.
+ * @since 0.11.0
+ */
+export function optionalWhen<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  const dependsOn = { ...normalizeOptionCondition(condition), required: false };
+  const names = optionNamesFromSpec(flagSpec);
+  return valueParser == null
+    ? option(...names, { dependsOn })
+    : option(...names, valueParser, { dependsOn });
+}
+
+/**
+ * Creates an option whose condition may include its requiredness.
+ * @since 0.11.0
+ */
+export function conditionalOption<M extends Mode, T>(
+  condition: OptionCondition,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  const dependsOn = normalizeOptionCondition(condition);
+  const names = optionNamesFromSpec(flagSpec);
+  return valueParser == null
+    ? option(...names, { dependsOn })
+    : option(...names, valueParser, { dependsOn });
+}
